import math

def is_power_of_5(num):
    if num <= 0:
        return False
    if num == 1:
        return True # 5^0 = 1, but we expect k >= 1 since 2^3 - 3 = 5^1

    # Check if num is a power of 5 by repeatedly dividing by 5
    while num > 1 and num % 5 == 0:
        num //= 5
    return num == 1

solutions = []
# Check up to n=100 for robustness, though previous rounds stopped at 60.
limit = 100 

for n in range(3, limit + 1):
    x = 2**n - 3
    if is_power_of_5(x):
        # Find the exponent k such that x = 5^k
        k = round(math.log(x, 5))
        solutions.append((n, k, x))

print("Solutions found (n, k, 5^k):")
for n, k, x in solutions:
    print(f"n={n}, k={k}, 2^n - 3 = {x}")

print(f"Total solutions found up to n={limit}: {len(solutions)}")

import math

def is_power_of_five(N):
    if N <= 0:
        return False
    if N == 1:
        return True
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

for m in range(5, 11): # n = 4*m + 3, m starts from 5 (n=23) up to m=10 (n=43)
    n = 4 * m + 3
    try:
        val = pow(2, n) - 3
        if is_power_of_five(val):
            print(f"n={n}: {val} is a power of 5.")
        else:
            print(f"n={n}: {val} is NOT a power of 5.")
    except OverflowError:
        print(f"n={n}: Calculation overflowed standard integer types.")
